package com.project.system.service;
import java.util.*;import java.math.BigDecimal;import java.time.*;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class MerchantConsumptionService{
 @Autowired private JdbcTemplate db;@Autowired private WalletService wallets;
 public List<Map<String,Object>> merchants(){return db.queryForList("select id,name,active from campus_merchant where id<>3 order by id");}
 @Transactional public Map<String,Object> consume(long merchant,String student,BigDecimal amount,String key,long actor){if(merchant==3)throw new IllegalArgumentException("请选择经营商户，模拟划扣不属于商户消费");if(student==null||student.trim().isEmpty())throw new IllegalArgumentException("请输入学工号");List<Map<String,Object>> users=db.queryForList("select user_id from sys_user where login_name=? and del_flag='0'",student.trim());if(users.size()!=1)throw new IllegalArgumentException("学工号不存在或不唯一");long user=((Number)users.get(0).get("user_id")).longValue();long id=wallets.trade(user,"PAY",amount,merchant,null,key,actor);return wallets.receipt(id);}
 private final String from=" from campus_ledger l left join campus_ledger original on l.original_id=original.id join sys_user u on u.user_id=l.user_id join campus_wallet w on w.user_id=l.user_id where l.kind in ('PAY','REFUND') and coalesce(l.merchant_id,original.merchant_id)<>3";
 private Map<String,Object> sums(String where,List<Object>a){return db.queryForMap("select coalesce(sum(case when l.kind='PAY' then l.amount else 0 end),0) income,coalesce(sum(case when l.kind='REFUND' then l.amount else 0 end),0) refunds,coalesce(sum(case when l.kind='PAY' then l.amount else -l.amount end),0) net"+from+where,a.toArray());}
 public Map<String,Object> query(Long merchant,String student,String phone,String start,String end,int page){if(merchant!=null&&merchant==3)throw new IllegalArgumentException("系统划扣商户不纳入经营收入");String scope="";List<Object> scopeArgs=new ArrayList<>();if(merchant!=null){scope=" and coalesce(l.merchant_id,original.merchant_id)=?";scopeArgs.add(merchant);}LocalDate today=LocalDate.now(ZoneId.of("Asia/Shanghai"));Map<String,Object> out=new LinkedHashMap<>();for(String period:Arrays.asList("day","month","year")){LocalDate begin=period.equals("day")?today:period.equals("month")?today.withDayOfMonth(1):today.withDayOfYear(1);List<Object>a=new ArrayList<>(scopeArgs);a.add(begin.toString());a.add(today.plusDays(1).toString());out.put(period,sums(scope+" and l.created_at>=? and l.created_at<?",a));}out.put("asOf",today.toString());String where=scope;List<Object>a=new ArrayList<>(scopeArgs);if(student!=null&&!student.trim().isEmpty()){where+=" and w.student_no=?";a.add(student.trim());}if(phone!=null&&!phone.trim().isEmpty()){where+=" and u.phonenumber=?";a.add(phone.trim());}for(String date:Arrays.asList(start,end))if(date!=null&&!date.isEmpty())try{LocalDate.parse(date);}catch(Exception e){throw new IllegalArgumentException("日期格式无效");}if(start!=null&&end!=null&&!start.isEmpty()&&!end.isEmpty()&&start.compareTo(end)>0)throw new IllegalArgumentException("开始日期不能晚于结束日期");if(start!=null&&!start.isEmpty()){where+=" and l.created_at>=?";a.add(start);}if(end!=null&&!end.isEmpty()){where+=" and l.created_at<date_add(?,interval 1 day)";a.add(end);}out.put("summary",sums(where,a));out.put("total",db.queryForObject("select count(*)"+from+where,Long.class,a.toArray()));a.add(20);a.add((Math.max(1,Math.min(page,100000))-1)*20);out.put("rows",db.queryForList("select l.transaction_no,l.kind,l.merchant_name_snapshot,l.amount,l.created_at,w.student_no,u.user_name,u.phonenumber,original.transaction_no original_no"+from+where+" order by l.id desc limit ? offset ?",a.toArray()));return out;}
}
